use std::collections::{BTreeMap, BTreeSet, HashMap, HashSet};
use std::env;
use std::fs;
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};

#[derive(Clone)]
struct Options {
    background: String,
    fill_color: String,
    stroke_color: String,
    font_family: String,
    font_size: u32,
    stroke_width: String,
    scale: f32,
    output: Option<String>,
}

impl Default for Options {
    fn default() -> Self {
        Options {
            background: "white".to_string(),
            fill_color: "black".to_string(),
            stroke_color: "black".to_string(),
            font_family: "Iosevka Fixed, monospace".to_string(),
            font_size: 14,
            stroke_width: "2".to_string(),
            scale: 1.0,
            output: None,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
struct Pt { x: i32, y: i32 }

#[derive(Clone, Debug)]
struct LineSeg {
    a: Pt,
    b: Pt,
    class_name: String,
    order: (i32, i32, i32),
}

#[derive(Clone, Debug)]
struct Elem {
    key: (i32, i32, i32),
    seq: usize,
    body: String,
}

fn main() {
    let code = run();
    std::process::exit(code);
}

fn run() -> i32 {
    let args: Vec<String> = env::args().skip(1).collect();
    if args.first().map(|s| s.as_str()) == Some("build") {
        return run_build(&args[1..]);
    }
    if args.first().map(|s| s.as_str()) == Some("help") {
        if args.get(1).map(|s| s.as_str()) == Some("build") {
            print_build_help();
        } else {
            print_help();
        }
        return 0;
    }

    let mut opts = Options::default();
    let mut inline = false;
    let mut input: Option<String> = None;
    let mut stop_options = false;
    let mut i = 0usize;
    while i < args.len() {
        let a = &args[i];
        if !stop_options && a == "--" {
            stop_options = true;
            i += 1;
            continue;
        }
        if !stop_options && (a == "--help" || a == "-h") {
            print_help();
            return 0;
        }
        if !stop_options && (a == "--version" || a == "-V") {
            println!("svgbob 0.7.6");
            return 0;
        }
        if !stop_options && a == "-s" {
            inline = true;
            i += 1;
            continue;
        }
        if !stop_options && (a == "--inline") {
            return clap_unknown(a, false);
        }
        if !stop_options && (a == "-o" || a == "--output") {
            match args.get(i+1) {
                Some(v) if !(v.starts_with('-') && !stop_options) => { opts.output = Some(v.clone()); i += 2; continue; }
                _ => return clap_missing("--output", "output", false),
            }
        }
        macro_rules! valopt {
            ($long:expr, $field:ident) => {{
                if !stop_options && a == $long {
                    match args.get(i+1) {
                        Some(v) if !v.starts_with('-') => { opts.$field = v.clone(); i += 2; continue; }
                        _ => return clap_missing($long, &$long[2..], false),
                    }
                }
            }};
        }
        valopt!("--background", background);
        valopt!("--fill-color", fill_color);
        valopt!("--stroke-color", stroke_color);
        valopt!("--font-family", font_family);
        if !stop_options && a == "--font-size" {
            match args.get(i+1) {
                Some(v) if !v.starts_with('-') => match v.parse::<u32>() {
                    Ok(n) => { opts.font_size = n; i += 2; continue; }
                    Err(e) => { eprintln!("Illegal value for argument font-size: {}", e); return 1; }
                },
                _ => return clap_missing("--font-size", "font-size", false),
            }
        }
        if !stop_options && a == "--stroke-width" {
            match args.get(i+1) {
                Some(v) if !v.starts_with('-') => { opts.stroke_width = v.clone(); i += 2; continue; }
                _ => return clap_missing("--stroke-width", "stroke-width", false),
            }
        }
        if !stop_options && a == "--scale" {
            match args.get(i+1) {
                Some(v) if !v.starts_with('-') => match v.parse::<f32>() {
                    Ok(n) => { opts.scale = n; i += 2; continue; }
                    Err(e) => { eprintln!("Illegal value for argument scale: {}", e); return 1; }
                },
                _ => return clap_missing("--scale", "scale", false),
            }
        }
        if !stop_options && a.starts_with('-') {
            // A close approximation of clap's public diagnostics.
            let shown = if a.starts_with("---") { "--" } else { a.as_str() };
            return clap_unknown(shown, false);
        }
        if input.is_none() {
            input = Some(a.clone());
            i += 1;
        } else {
            return clap_unknown(a, false);
        }
    }

    let data = if inline {
        match input {
            Some(s) => s,
            None => {
                eprintln!("\nthread 'main' ({}) panicked at crates/svgbob_cli/src/main.rs:84:38:", std::process::id());
                eprintln!("called `Option::unwrap()` on a `None` value");
                eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
                return 101;
            }
        }
    } else if let Some(path) = input {
        match fs::read_to_string(&path) {
            Ok(s) => s,
            Err(e) => { eprintln!("Failed to open input file {}: {}", path, e); return 1; }
        }
    } else {
        let mut s = String::new();
        let _ = io::stdin().read_to_string(&mut s);
        s
    };

    let svg = render_svg(&data, &opts);
    if let Some(out) = &opts.output {
        match fs::File::create(out).and_then(|mut f| f.write_all(svg.as_bytes())) {
            Ok(_) => 0,
            Err(e) => { eprintln!("Failed to create output file {}: {}", out, e); 1 }
        }
    } else {
        print!("{}", svg);
        0
    }
}

fn clap_unknown(arg: &str, build: bool) -> i32 {
    eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", arg);
    eprintln!();
    if build {
        eprintln!("USAGE:");
        eprintln!("    executable build [OPTIONS]");
    } else {
        eprintln!("USAGE:");
        eprintln!("    executable [FLAGS] [OPTIONS] [input] [SUBCOMMAND]");
    }
    eprintln!();
    eprintln!("For more information try --help");
    1
}

fn clap_missing(long: &str, name: &str, build: bool) -> i32 {
    let canonical = match long {
        "-o" => "--output",
        "-i" => "--input",
        _ => long,
    };
    eprintln!("error: The argument '{} <{}>' requires a value but none was supplied", canonical, name);
    eprintln!();
    eprintln!("USAGE:");
    if build {
        eprintln!("    executable build {} <{}>", canonical, name);
    } else {
        eprintln!("    executable {} <{}>", canonical, name);
    }
    eprintln!();
    eprintln!("For more information try --help");
    1
}

