fn print_build_help() {
    println!("executable-build 0.0.1");
    println!("Batch convert files to svg.");
    println!();
    println!("USAGE:");
    println!("    executable build [OPTIONS]");
    println!();
    println!("FLAGS:");
    println!("    -h, --help       Prints help information");
    println!("    -V, --version    Prints version information");
    println!();
    println!("OPTIONS:");
    println!("    -i, --input <input>      set input file pattern like: *.bob or dir/*.bob");
    println!("    -o, --outdir <outdir>    set dir of svg files");
}

fn run_build(args: &[String]) -> i32 {
    let mut input = String::new();
    let mut outdir = String::new();
    let mut i = 0usize;
    while i < args.len() {
        let a = &args[i];
        if a == "--help" || a == "-h" { print_build_help(); return 0; }
        if a == "--version" || a == "-V" { println!("executable-build 0.0.1"); return 0; }
        if a == "-i" || a == "--input" {
            match args.get(i+1) { Some(v) if !v.starts_with('-') => { input = v.clone(); i += 2; continue; }, _ => return clap_missing("--input", "input", true) }
        }
        if a == "-o" || a == "--outdir" {
            match args.get(i+1) { Some(v) if !v.starts_with('-') => { outdir = v.clone(); i += 2; continue; }, _ => return clap_missing("--outdir", "outdir", true) }
        }
        if a.starts_with('-') { return clap_unknown(a, true); }
        i += 1;
    }
    if input.is_empty() || outdir.is_empty() {
        println!("[Error]: No such dir name is  !");
        return 1;
    }
    let (dir, ext) = split_build_pattern(&input);
    if !Path::new(&dir).is_dir() {
        println!("[Error]: No such dir name is {} !", dir);
        return 1;
    }
    let _ = fs::create_dir_all(&outdir);
    let mut entries: Vec<PathBuf> = Vec::new();
    if let Ok(rd) = fs::read_dir(&dir) {
        for e in rd.flatten() {
            let p = e.path();
            if p.is_file() {
                let ok = if ext.is_empty() { true } else { p.extension().and_then(|s| s.to_str()).map(|s| s == ext).unwrap_or(false) };
                if ok { entries.push(p); }
            }
        }
    }
    entries.sort();
    for p in entries {
        let data = fs::read_to_string(&p).unwrap_or_default();
        let svg = render_svg(&data, &Options::default());
        let stem = p.file_stem().and_then(|s| s.to_str()).unwrap_or("out");
        let out = Path::new(&outdir).join(format!("{}.svg", stem));
        println!("{} => {}", p.display(), out.display());
        let _ = fs::write(out, svg);
    }
    1
}

fn split_build_pattern(s: &str) -> (String, String) {
    let p = Path::new(s);
    let dir = p.parent().and_then(|d| if d.as_os_str().is_empty() { None } else { Some(d.to_string_lossy().to_string()) }).unwrap_or_else(|| ".".to_string());
    let fname = p.file_name().and_then(|f| f.to_str()).unwrap_or("");
    let ext = if let Some(pos) = fname.rfind('.') { fname[pos+1..].trim_matches('*').to_string() } else { String::new() };
    (dir, ext)
}

fn normalize_input(input: &str) -> Vec<Vec<char>> {
    let s = input.replace("\r\n", "\n").replace('\r', "");
    let mut lines: Vec<String> = s.split('\n').map(|x| x.to_string()).collect();
    if s.ends_with('\n') { lines.pop(); }
    while lines.last().map(|l| l.trim_end().is_empty()).unwrap_or(false) { lines.pop(); }
    if lines.is_empty() { return vec![Vec::new()]; }
    let mut out = Vec::new();
    for mut l in lines {
        while l.ends_with(' ') || l.ends_with('\t') { l.pop(); }
        out.push(l.chars().collect());
    }
    out
}

fn ch_at(grid: &[Vec<char>], r: i32, c: i32) -> char {
    if r < 0 || c < 0 { return ' '; }
    grid.get(r as usize).and_then(|row| row.get(c as usize)).copied().unwrap_or(' ')
}

fn is_h_basic(ch: char) -> bool { matches!(ch, '-' | '~' | '+') }
fn is_v_basic(ch: char) -> bool { matches!(ch, '|' | '+') }

fn render_svg(input: &str, opts: &Options) -> String {
    let grid = normalize_input(input);
    let rows = grid.len().max(1);
    let cols = grid.iter().map(|r| r.len()).max().unwrap_or(0).max(1);
    let width = ((cols as i32 + 1) * 8) as f32 * opts.scale;
    let height = ((rows as i32 + 1) * 16) as f32 * opts.scale;

    let mut used: HashSet<(usize, usize)> = HashSet::new();
    let mut elems: Vec<Elem> = Vec::new();
    let mut seq = 0usize;

    detect_rects(&grid, &mut used, &mut elems, opts, &mut seq);

    let mut lines: Vec<LineSeg> = Vec::new();
    let mut polygons: Vec<Elem> = Vec::new();
    collect_lines_and_markers(&grid, &mut used, &mut lines, &mut polygons, opts, &mut seq);

    // Text is collected before line components are appended; final sorting by row/x
    // reproduces the usual left-to-right interleaving of text and strokes.
    collect_text(&grid, &used, &mut elems, opts, &mut seq);

    let line_elems = build_line_elements(lines, opts, &mut seq);
    elems.extend(polygons);
    elems.extend(line_elems);
    elems.sort_by(|a,b| a.key.cmp(&b.key).then(a.seq.cmp(&b.seq)));

    let mut out = String::new();
    out.push_str(&format!("<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"{}\" height=\"{}\" class=\"svgbob\">\n", fmt_f(width), fmt_f(height)));
    out.push_str(&style_defs(opts));
    out.push_str(&format!("  <rect class=\"backdrop\" x=\"0\" y=\"0\" width=\"{}\" height=\"{}\"></rect>\n", fmt_f(width), fmt_f(height)));
    for e in elems { out.push_str(&e.body); }
    out.push_str("</svg>\n");
    out
}

