fn fmt_f(x: f32) -> String { format!("{}", x) }
fn sf(v: i32, opts: &Options) -> String { fmt_f((v as f32) * opts.scale) }

fn esc(s: &str) -> String {
    let mut out = String::new();
    for ch in s.chars() {
        match ch {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            _ => out.push(ch),
        }
    }
    out
}

fn detect_rects(grid: &[Vec<char>], used: &mut HashSet<(usize,usize)>, elems: &mut Vec<Elem>, opts: &Options, seq: &mut usize) {
    let rows = grid.len();
    let cols = grid.iter().map(|r| r.len()).max().unwrap_or(0);
    for r1 in 0..rows {
        for c1 in 0..cols {
            if used.contains(&(r1,c1)) { continue; }
            let tl = ch_at(grid, r1 as i32, c1 as i32);
            if tl != '+' && tl != '.' { continue; }
            let mut best: Option<(usize,usize,bool,String)> = None; // r2,c2,round,class
            for r2 in (r1+1)..rows {
                for c2 in (c1+1)..cols {
                    let tr = ch_at(grid, r1 as i32, c2 as i32);
                    let bl = ch_at(grid, r2 as i32, c1 as i32);
                    let br = ch_at(grid, r2 as i32, c2 as i32);
                    let round = tl == '.' && tr == '.' && (bl == '\'' || bl == '`') && br == '\'';
                    let square = tl == '+' && tr == '+' && bl == '+' && br == '+';
                    if !round && !square { continue; }
                    let mut class_name = "solid".to_string();
                    let mut ok = true;
                    for c in (c1+1)..c2 {
                        let top = ch_at(grid, r1 as i32, c as i32);
                        let bot = ch_at(grid, r2 as i32, c as i32);
                        if top == '~' && bot == '~' { class_name = "broken".to_string(); }
                        else if top != '-' || bot != '-' { ok = false; break; }
                    }
                    if !ok { continue; }
                    for r in (r1+1)..r2 {
                        if ch_at(grid, r as i32, c1 as i32) != '|' || ch_at(grid, r as i32, c2 as i32) != '|' { ok = false; break; }
                    }
                    if !ok { continue; }
                    let area = (r2-r1)*(c2-c1);
                    let best_area = best.map(|(br,bc,_,_)| (br-r1)*(bc-c1)).unwrap_or(0);
                    if area > best_area { best = Some((r2,c2,round,class_name)); }
                }
            }
            if let Some((r2,c2,round,class_name)) = best {
                // mark border
                for c in c1..=c2 { used.insert((r1,c)); used.insert((r2,c)); }
                for r in r1..=r2 { used.insert((r,c1)); used.insert((r,c2)); }
                let x = c1 as i32 * 8 + 4;
                let y = r1 as i32 * 16 + 8;
                let w = (c2 as i32 - c1 as i32) * 8;
                let h = (r2 as i32 - r1 as i32) * 16;
                let rx = if round { 4 } else { 0 };
                let body = format!("  <rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" class=\"{} nofill\" rx=\"{}\"></rect>\n",
                    sf(x,opts), sf(y,opts), sf(w,opts), sf(h,opts), class_name, sf(rx,opts));
                elems.push(Elem{ key:(r1 as i32, x, 0), seq:*seq, body }); *seq += 1;
            }
        }
    }
}

fn collect_lines_and_markers(grid: &[Vec<char>], used: &mut HashSet<(usize,usize)>, lines: &mut Vec<LineSeg>, polygons: &mut Vec<Elem>, opts: &Options, seq: &mut usize) {
    let rows = grid.len() as i32;
    let cols = grid.iter().map(|r| r.len()).max().unwrap_or(0) as i32;
    let mut add_line = |a: Pt, b: Pt, class_name: &str, order: (i32,i32,i32), mark_cells: &[(usize,usize)]| {
        if a == b && !class_name.contains("marked") { return; }
        lines.push(LineSeg{a,b,class_name:class_name.to_string(),order});
        for &m in mark_cells { used.insert(m); }
    };

    // Horizontal solid/broken runs and arrow heads/markers.
    for r in 0..rows {
        let y = r*16 + 8;
        let mut c = 0;
        while c < cols {
            if used.contains(&(r as usize,c as usize)) { c += 1; continue; }
            let ch = ch_at(grid,r,c);
            if ch == '=' {
                let start = c;
                while c < cols && ch_at(grid,r,c) == '=' && !used.contains(&(r as usize,c as usize)) { used.insert((r as usize,c as usize)); c += 1; }
                for dy in [-2,2] { add_line(Pt{x:start*8,y:y+dy}, Pt{x:c*8,y:y+dy}, "solid", (r,start*8,1), &[]); }
                continue;
            }
            if ch == '-' || ch == '~' || ch == '+' || ch == '<' || ch == '>' || ch == 'o' || ch == 'O' || ch == '*' {
                let start = c;
                let mut end = c;
                while end < cols {
                    let cc = ch_at(grid,r,end);
                    if used.contains(&(r as usize,end as usize)) { break; }
                    if matches!(cc, '-'|'~'|'+'|'<'|'>'|'o'|'O'|'*') { end += 1; } else { break; }
                }
                if end == start { c += 1; continue; }
                let slice: Vec<char> = (start..end).map(|k| ch_at(grid,r,k)).collect();
                let has_line = slice.iter().any(|&x| x == '-' || x == '~') || slice.iter().filter(|&&x| x=='+').count() >= 2;
                if !has_line { c += 1; continue; }
                // Do not consume lone arrow/marker glyphs unless they are adjacent to a line char.
                for k in start..end { used.insert((r as usize,k as usize)); }
                let broken = slice.iter().any(|&x| x == '~');
                let base_class = if broken { "broken" } else { "solid" };
                // arrow polygons
                let mut body_start = start*8;
                let mut body_end = end*8;
                if ch_at(grid,r,start) == '<' {
                    let pts = format!("{},{} {},{} {},{}", sf(start*8+8,opts), sf(y-4,opts), sf(start*8,opts), sf(y,opts), sf(start*8+8,opts), sf(y+4,opts));
                    polygons.push(Elem{key:(r,start*8,0),seq:*seq,body:format!("  <polygon points=\"{}\" class=\"filled\"></polygon>\n", pts)}); *seq+=1;
                    body_start = start*8+8;
                }
                if ch_at(grid,r,end-1) == '>' {
                    let k = end-1;
                    let pts = format!("{},{} {},{} {},{}", sf(k*8,opts), sf(y-4,opts), sf(k*8+8,opts), sf(y,opts), sf(k*8,opts), sf(y+4,opts));
                    polygons.push(Elem{key:(r,k*8,0),seq:*seq,body:format!("  <polygon points=\"{}\" class=\"filled\"></polygon>\n", pts)}); *seq+=1;
                    body_end = k*8;
                }
                // Start marker handling.
                let first = ch_at(grid,r,start);
                if matches!(first, 'o'|'O') {
                    let cls = if first=='O' { "solid end_marked_big_open_circle" } else { "solid end_marked_open_circle" };
                    add_line(Pt{x:start*8+16,y}, Pt{x:start*8+4,y}, cls, (r,start*8,1), &[]);
                    body_start = (start*8+16).min(body_end);
                } else if first == '*' {
                    add_line(Pt{x:start*8+4,y}, Pt{x:start*8+4,y}, "solid end_marked_circle", (r,start*8,1), &[]);
                    body_start = (start*8+8).min(body_end);
                } else if first == '+' { body_start = start*8 + 4; }
                let last = ch_at(grid,r,end-1);
                let mut end_marker_class = "";
                if matches!(last, 'o'|'O'|'*') {
                    body_end = (end-1)*8 + 4;
                    end_marker_class = match last { 'o' => " end_marked_open_circle", 'O' => " end_marked_big_open_circle", '*' => " end_marked_circle", _ => "" };
                } else if last == '+' { body_end = (end-1)*8 + 4; }
                // If run contains middle marker, split roughly at marker positions.
                let mut parts: Vec<(i32,i32,String)> = vec![(body_start, body_end, format!("{}{}", base_class, end_marker_class))];
                if slice.len() > 2 {
                    for (idx,&cc) in slice.iter().enumerate().skip(1).take(slice.len().saturating_sub(2)) {
                        if matches!(cc,'o'|'O'|'*') {
                            let mx = (start + idx as i32)*8 + 4;
                            let cls = match cc { 'o'=>"solid end_marked_open_circle", 'O'=>"solid end_marked_big_open_circle", '*'=>"solid end_marked_circle", _=>"solid" };
                            parts.clear();
                            parts.push((body_start, mx, cls.to_string()));
                            parts.push(((start + idx as i32 + 1)*8, body_end, base_class.to_string()));
                            break;
                        }
                    }
                }
                for (x1,x2,cls) in parts { if x2 >= x1 { add_line(Pt{x:x1,y}, Pt{x:x2,y}, &cls, (r,x1,2), &[]); } }
                c = end;
                continue;
            }
            c += 1;
        }
    }

    // Vertical runs with ^/v and markers.
    for c in 0..cols {
        let mut r = 0;
        while r < rows {
            if used.contains(&(r as usize,c as usize)) { r += 1; continue; }
            let ch = ch_at(grid,r,c);
            if matches!(ch, '|'|'+'|'^'|'v'|'o'|'O'|'*') {
                let start = r;
                let mut end = r;
                while end < rows {
                    let cc = ch_at(grid,end,c);
                    if used.contains(&(end as usize,c as usize)) { break; }
                    if matches!(cc, '|'|'+'|'^'|'v'|'o'|'O'|'*') { end += 1; } else { break; }
                }
                let slice: Vec<char> = (start..end).map(|k| ch_at(grid,k,c)).collect();
                let has_line = slice.iter().any(|&x| x == '|') || slice.iter().filter(|&&x| x=='+').count() >= 2;
                if !has_line { r += 1; continue; }
                for k in start..end { used.insert((k as usize,c as usize)); }
                let x = c*8 + 4;
                let mut y1 = start*16;
                let mut y2 = end*16;
                if ch_at(grid,start,c) == '+' { y1 = start*16+8; }
                if ch_at(grid,end-1,c) == '+' { y2 = (end-1)*16+8; }
                if ch_at(grid,start,c) == '^' {
                    let yy = start*16;
                    let pts = format!("{},{} {},{} {},{}", sf(x-4,opts), sf(yy+12,opts), sf(x,opts), sf(yy,opts), sf(x+4,opts), sf(yy+12,opts));
                    polygons.push(Elem{key:(start,x,0),seq:*seq,body:format!("  <polygon points=\"{}\" class=\"filled\"></polygon>\n", pts)}); *seq+=1;
                    y1 = yy+12;
                }
                if ch_at(grid,end-1,c) == 'v' {
                    let yy = (end-1)*16;
                    let pts = format!("{},{} {},{} {},{}", sf(x-4,opts), sf(yy+4,opts), sf(x+4,opts), sf(yy+4,opts), sf(x,opts), sf(yy+16,opts));
                    polygons.push(Elem{key:(end-1,x,0),seq:*seq,body:format!("  <polygon points=\"{}\" class=\"filled\"></polygon>\n", pts)}); *seq+=1;
                    y2 = yy+4;
                }
                let first = ch_at(grid,start,c);
                if matches!(first,'o'|'O') {
                    let cls = if first=='O' { "solid end_marked_big_open_circle" } else { "solid end_marked_open_circle" };
                    add_line(Pt{x,y:start*16+12}, Pt{x,y:start*16+8}, cls, (start,x,1), &[]);
                    y1 = start*16+16;
                } else if first == '*' {
                    add_line(Pt{x,y:start*16+12}, Pt{x,y:start*16+8}, "solid end_marked_circle", (start,x,1), &[]);
                    y1 = start*16+16;
                }
                let last = ch_at(grid,end-1,c);
                let cls = if last=='o' { y2=(end-1)*16+8; "solid end_marked_open_circle" }
                    else if last=='O' { y2=(end-1)*16+8; "solid end_marked_big_open_circle" }
                    else if last=='*' { y2=(end-1)*16+8; "solid end_marked_circle" }
                    else { "solid" };
                if y2 >= y1 { add_line(Pt{x,y:y1}, Pt{x,y:y2}, cls, (start,x,2), &[]); }
                r = end;
                continue;
            }
            r += 1;
        }
    }

    // Diagonals, merged when consecutive glyphs continue the same slope.
    let mut seen_diag: HashSet<(i32,i32)> = HashSet::new();
    for r in 0..rows {
        for c in 0..cols {
            if used.contains(&(r as usize,c as usize)) || seen_diag.contains(&(r,c)) { continue; }
            let ch = ch_at(grid,r,c);
            if ch == '\\' {
                let mut rr=r; let mut cc=c;
                while ch_at(grid,rr,cc)=='\\' && !used.contains(&(rr as usize,cc as usize)) { seen_diag.insert((rr,cc)); used.insert((rr as usize,cc as usize)); rr+=1; cc+=1; }
                add_line(Pt{x:c*8,y:r*16}, Pt{x:cc*8,y:rr*16}, "solid", (r,c*8,3), &[]);
            } else if ch == '/' {
                let mut rr=r; let mut cc=c;
                while ch_at(grid,rr,cc)=='/' && !used.contains(&(rr as usize,cc as usize)) { seen_diag.insert((rr,cc)); used.insert((rr as usize,cc as usize)); rr+=1; cc-=1; }
                add_line(Pt{x:(c+1)*8,y:r*16}, Pt{x:(cc+1)*8,y:rr*16}, "solid", (r,c*8,3), &[]);
            }
        }
    }
}

fn collect_text(grid: &[Vec<char>], used: &HashSet<(usize,usize)>, elems: &mut Vec<Elem>, opts: &Options, seq: &mut usize) {
    for (r,row) in grid.iter().enumerate() {
        let mut c=0usize;
        while c < row.len() {
            while c < row.len() && (row[c].is_whitespace() || used.contains(&(r,c))) { c+=1; }
            if c>=row.len() { break; }
            let start=c;
            let mut s=String::new();
            while c < row.len() && !row[c].is_whitespace() && !used.contains(&(r,c)) {
                s.push(row[c]); c+=1;
            }
            let x = start as i32 * 8 + 2;
            let y = r as i32 * 16 + 12;
            let body = format!("  <text x=\"{}\" y=\"{}\" >{}</text>\n", sf(x,opts), sf(y,opts), esc(&s));
            elems.push(Elem{key:(r as i32, start as i32*8, 5), seq:*seq, body}); *seq+=1;
        }
    }
}

fn build_line_elements(mut lines: Vec<LineSeg>, opts: &Options, seq: &mut usize) -> Vec<Elem> {
    // Merge simple unmarked collinear segments with identical classes.
    lines = merge_lines(lines);
    lines.sort_by_key(|l| l.order);
    let n = lines.len();
    let mut adj: Vec<Vec<usize>> = vec![Vec::new(); n];
    let mut pts: HashMap<Pt, Vec<usize>> = HashMap::new();
    for (i,l) in lines.iter().enumerate() {
        pts.entry(l.a).or_default().push(i);
        pts.entry(l.b).or_default().push(i);
    }
    for ids in pts.values() {
        for &i in ids { for &j in ids { if i!=j { adj[i].push(j); } } }
    }
    let mut seen = vec![false; n];
    let mut elems = Vec::new();
    for i in 0..n {
        if seen[i] { continue; }
        let mut stack=vec![i]; seen[i]=true; let mut comp=Vec::new();
        while let Some(k)=stack.pop() { comp.push(k); for &j in &adj[k] { if !seen[j] { seen[j]=true; stack.push(j); } } }
        comp.sort_by_key(|&k| lines[k].order);
        let key_line = &lines[comp[0]];
        let key = key_line.order;
        let mut body = String::new();
        if comp.len()>1 { body.push_str("  <g>\n"); }
        for &idx in &comp {
            let l=&lines[idx];
            let indent = if comp.len()>1 { "    " } else { "  " };
            body.push_str(&format!("{}<line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>\n",
                indent, sf(l.a.x,opts), sf(l.a.y,opts), sf(l.b.x,opts), sf(l.b.y,opts), l.class_name));
        }
        if comp.len()>1 { body.push_str("  </g>\n"); }
        elems.push(Elem{key,seq:*seq,body}); *seq+=1;
    }
    elems
}

fn merge_lines(lines: Vec<LineSeg>) -> Vec<LineSeg> {
    let mut result: Vec<LineSeg> = Vec::new();
    let mut groups: BTreeMap<(String, bool, i32), Vec<LineSeg>> = BTreeMap::new();
    for mut l in lines {
        // normalize direction for plain lines only
        let marked = l.class_name.contains("marked");
        if !marked {
            if (l.a.y == l.b.y && l.a.x > l.b.x) || (l.a.x == l.b.x && l.a.y > l.b.y) {
                std::mem::swap(&mut l.a, &mut l.b);
            }
        }
        if marked || (l.a.x != l.b.x && l.a.y != l.b.y) {
            result.push(l);
        } else if l.a.y == l.b.y {
            groups.entry((l.class_name.clone(), true, l.a.y)).or_default().push(l);
        } else {
            groups.entry((l.class_name.clone(), false, l.a.x)).or_default().push(l);
        }
    }
    for ((_cls,horiz,_fixed), mut v) in groups {
        v.sort_by_key(|l| if horiz { (l.a.x,l.b.x) } else { (l.a.y,l.b.y) });
        let mut cur: Option<LineSeg> = None;
        for l in v {
            if let Some(mut c) = cur.take() {
                if horiz && l.a.x <= c.b.x {
                    if l.b.x > c.b.x { c.b.x = l.b.x; }
                    c.order = c.order.min(l.order); cur = Some(c);
                } else if !horiz && l.a.y <= c.b.y {
                    if l.b.y > c.b.y { c.b.y = l.b.y; }
                    c.order = c.order.min(l.order); cur = Some(c);
                } else { result.push(c); cur = Some(l); }
            } else { cur = Some(l); }
        }
        if let Some(c) = cur { result.push(c); }
    }
    result.sort_by_key(|l| l.order);
    result
}
