cat > src/main.rs <<'RS'
use std::collections::{BTreeMap, BTreeSet, HashMap, HashSet};
use std::env;
use std::fs;
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};

#[derive(Clone)]
struct Options {
    background: String,
    fill_color: String,
    stroke_color: String,
    font_family: String,
    font_size: u32,
    stroke_width: String,
    scale: f32,
    output: Option<String>,
}

impl Default for Options {
    fn default() -> Self {
        Options {
            background: "white".to_string(),
            fill_color: "black".to_string(),
            stroke_color: "black".to_string(),
            font_family: "Iosevka Fixed, monospace".to_string(),
            font_size: 14,
            stroke_width: "2".to_string(),
            scale: 1.0,
            output: None,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
struct Pt { x: i32, y: i32 }

#[derive(Clone, Debug)]
struct LineSeg {
    a: Pt,
    b: Pt,
    class_name: String,
    order: (i32, i32, i32),
}

#[derive(Clone, Debug)]
struct Elem {
    key: (i32, i32, i32),
    seq: usize,
    body: String,
}

fn main() {
    let code = run();
    std::process::exit(code);
}

fn run() -> i32 {
    let args: Vec<String> = env::args().skip(1).collect();
    if args.first().map(|s| s.as_str()) == Some("build") {
        return run_build(&args[1..]);
    }
    if args.first().map(|s| s.as_str()) == Some("help") {
        if args.get(1).map(|s| s.as_str()) == Some("build") {
            print_build_help();
        } else {
            print_help();
        }
        return 0;
    }

    let mut opts = Options::default();
    let mut inline = false;
    let mut input: Option<String> = None;
    let mut stop_options = false;
    let mut i = 0usize;
    while i < args.len() {
        let a = &args[i];
        if !stop_options && a == "--" {
            stop_options = true;
            i += 1;
            continue;
        }
        if !stop_options && (a == "--help" || a == "-h") {
            print_help();
            return 0;
        }
        if !stop_options && (a == "--version" || a == "-V") {
            println!("svgbob 0.7.6");
            return 0;
        }
        if !stop_options && a == "-s" {
            inline = true;
            i += 1;
            continue;
        }
        if !stop_options && (a == "--inline") {
            return clap_unknown(a, false);
        }
        if !stop_options && (a == "-o" || a == "--output") {
            match args.get(i+1) {
                Some(v) if !(v.starts_with('-') && !stop_options) => { opts.output = Some(v.clone()); i += 2; continue; }
                _ => return clap_missing("--output", "output", false),
            }
        }
        macro_rules! valopt {
            ($long:expr, $field:ident) => {{
                if !stop_options && a == $long {
                    match args.get(i+1) {
                        Some(v) if !v.starts_with('-') => { opts.$field = v.clone(); i += 2; continue; }
                        _ => return clap_missing($long, &$long[2..], false),
                    }
                }
            }};
        }
        valopt!("--background", background);
        valopt!("--fill-color", fill_color);
        valopt!("--stroke-color", stroke_color);
        valopt!("--font-family", font_family);
        if !stop_options && a == "--font-size" {
            match args.get(i+1) {
                Some(v) if !v.starts_with('-') => match v.parse::<u32>() {
                    Ok(n) => { opts.font_size = n; i += 2; continue; }
                    Err(e) => { eprintln!("Illegal value for argument font-size: {}", e); return 1; }
                },
                _ => return clap_missing("--font-size", "font-size", false),
            }
        }
        if !stop_options && a == "--stroke-width" {
            match args.get(i+1) {
                Some(v) if !v.starts_with('-') => { opts.stroke_width = v.clone(); i += 2; continue; }
                _ => return clap_missing("--stroke-width", "stroke-width", false),
            }
        }
        if !stop_options && a == "--scale" {
            match args.get(i+1) {
                Some(v) if !v.starts_with('-') => match v.parse::<f32>() {
                    Ok(n) => { opts.scale = n; i += 2; continue; }
                    Err(e) => { eprintln!("Illegal value for argument scale: {}", e); return 1; }
                },
                _ => return clap_missing("--scale", "scale", false),
            }
        }
        if !stop_options && a.starts_with('-') {
            // A close approximation of clap's public diagnostics.
            let shown = if a.starts_with("---") { "--" } else { a.as_str() };
            return clap_unknown(shown, false);
        }
        if input.is_none() {
            input = Some(a.clone());
            i += 1;
        } else {
            return clap_unknown(a, false);
        }
    }

    let data = if inline {
        match input {
            Some(s) => s,
            None => {
                eprintln!("\nthread 'main' ({}) panicked at crates/svgbob_cli/src/main.rs:84:38:", std::process::id());
                eprintln!("called `Option::unwrap()` on a `None` value");
                eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
                return 101;
            }
        }
    } else if let Some(path) = input {
        match fs::read_to_string(&path) {
            Ok(s) => s,
            Err(e) => { eprintln!("Failed to open input file {}: {}", path, e); return 1; }
        }
    } else {
        let mut s = String::new();
        let _ = io::stdin().read_to_string(&mut s);
        s
    };

    let svg = render_svg(&data, &opts);
    if let Some(out) = &opts.output {
        match fs::File::create(out).and_then(|mut f| f.write_all(svg.as_bytes())) {
            Ok(_) => 0,
            Err(e) => { eprintln!("Failed to create output file {}: {}", out, e); 1 }
        }
    } else {
        print!("{}", svg);
        0
    }
}

fn clap_unknown(arg: &str, build: bool) -> i32 {
    eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", arg);
    eprintln!();
    if build {
        eprintln!("USAGE:");
        eprintln!("    executable build [OPTIONS]");
    } else {
        eprintln!("USAGE:");
        eprintln!("    executable [FLAGS] [OPTIONS] [input] [SUBCOMMAND]");
    }
    eprintln!();
    eprintln!("For more information try --help");
    1
}

fn clap_missing(long: &str, name: &str, build: bool) -> i32 {
    let canonical = match long {
        "-o" => "--output",
        "-i" => "--input",
        _ => long,
    };
    eprintln!("error: The argument '{} <{}>' requires a value but none was supplied", canonical, name);
    eprintln!();
    eprintln!("USAGE:");
    if build {
        eprintln!("    executable build {} <{}>", canonical, name);
    } else {
        eprintln!("    executable {} <{}>", canonical, name);
    }
    eprintln!();
    eprintln!("For more information try --help");
    1
}

fn print_help() {
    println!("svgbob 0.7.6");
    println!("SvgBobRus is an ascii to svg converter");
    println!();
    println!("USAGE:");
    println!("    executable [FLAGS] [OPTIONS] [input] [SUBCOMMAND]");
    println!();
    println!("FLAGS:");
    println!("    -h, --help       Prints help information");
    println!("    -s               parse an inline string");
    println!("    -V, --version    Prints version information");
    println!();
    println!("OPTIONS:");
    println!("        --background <background>        backdrop background will be filled with this color (default: 'white')");
    println!("        --fill-color <fill-color>        solid shapes will be filled with this color (default: 'black')");
    println!("        --font-family <font-family>      text will be rendered with this font (default: 'arial')");
    println!("        --font-size <font-size>          text will be rendered with this font size (default: 14)");
    println!("    -o, --output <output>                where to write svg output [default: STDOUT]");
    println!("        --scale <scale>                  scale the entire svg (dimensions, font size, stroke width) by this factor");
    println!("                                         (default: 1)");
    println!("        --stroke-color <stroke-color>    stroke color for all lines (default: 'black')");
    println!("        --stroke-width <stroke-width>    stroke width for all lines (default: 2)");
    println!();
    println!("ARGS:");
    println!("    <input>    svgbob text file or inline string to parse [default: STDIN]");
    println!();
    println!("SUBCOMMANDS:");
    println!("    build    Batch convert files to svg.");
    println!("    help     Prints this message or the help of the given subcommand(s)");
}

fn print_build_help() {
    println!("executable-build 0.0.1");
    println!("Batch convert files to svg.");
    println!();
    println!("USAGE:");
    println!("    executable build [OPTIONS]");
    println!();
    println!("FLAGS:");
    println!("    -h, --help       Prints help information");
    println!("    -V, --version    Prints version information");
    println!();
    println!("OPTIONS:");
    println!("    -i, --input <input>      set input file pattern like: *.bob or dir/*.bob");
    println!("    -o, --outdir <outdir>    set dir of svg files");
}

fn run_build(args: &[String]) -> i32 {
    let mut input = String::new();
    let mut outdir = String::new();
    let mut i = 0usize;
    while i < args.len() {
        let a = &args[i];
        if a == "--help" || a == "-h" { print_build_help(); return 0; }
        if a == "--version" || a == "-V" { println!("executable-build 0.0.1"); return 0; }
        if a == "-i" || a == "--input" {
            match args.get(i+1) { Some(v) if !v.starts_with('-') => { input = v.clone(); i += 2; continue; }, _ => return clap_missing("--input", "input", true) }
        }
        if a == "-o" || a == "--outdir" {
            match args.get(i+1) { Some(v) if !v.starts_with('-') => { outdir = v.clone(); i += 2; continue; }, _ => return clap_missing("--outdir", "outdir", true) }
        }
        if a.starts_with('-') { return clap_unknown(a, true); }
        i += 1;
    }
    if input.is_empty() || outdir.is_empty() {
        println!("[Error]: No such dir name is  !");
        return 1;
    }
    let (dir, ext) = split_build_pattern(&input);
    if !Path::new(&dir).is_dir() {
        println!("[Error]: No such dir name is {} !", dir);
        return 1;
    }
    let _ = fs::create_dir_all(&outdir);
    let mut entries: Vec<PathBuf> = Vec::new();
    if let Ok(rd) = fs::read_dir(&dir) {
        for e in rd.flatten() {
            let p = e.path();
            if p.is_file() {
                let ok = if ext.is_empty() { true } else { p.extension().and_then(|s| s.to_str()).map(|s| s == ext).unwrap_or(false) };
                if ok { entries.push(p); }
            }
        }
    }
    entries.sort();
    for p in entries {
        let data = fs::read_to_string(&p).unwrap_or_default();
        let svg = render_svg(&data, &Options::default());
        let stem = p.file_stem().and_then(|s| s.to_str()).unwrap_or("out");
        let out = Path::new(&outdir).join(format!("{}.svg", stem));
        println!("{} => {}", p.display(), out.display());
        let _ = fs::write(out, svg);
    }
    1
}

fn split_build_pattern(s: &str) -> (String, String) {
    let p = Path::new(s);
    let dir = p.parent().and_then(|d| if d.as_os_str().is_empty() { None } else { Some(d.to_string_lossy().to_string()) }).unwrap_or_else(|| ".".to_string());
    let fname = p.file_name().and_then(|f| f.to_str()).unwrap_or("");
    let ext = if let Some(pos) = fname.rfind('.') { fname[pos+1..].trim_matches('*').to_string() } else { String::new() };
    (dir, ext)
}

fn normalize_input(input: &str) -> Vec<Vec<char>> {
    let s = input.replace("\r\n", "\n").replace('\r', "");
    let mut lines: Vec<String> = s.split('\n').map(|x| x.to_string()).collect();
    if s.ends_with('\n') { lines.pop(); }
    while lines.last().map(|l| l.trim_end().is_empty()).unwrap_or(false) { lines.pop(); }
    if lines.is_empty() { return vec![Vec::new()]; }
    let mut out = Vec::new();
    for mut l in lines {
        while l.ends_with(' ') || l.ends_with('\t') { l.pop(); }
        out.push(l.chars().collect());
    }
    out
}

fn ch_at(grid: &[Vec<char>], r: i32, c: i32) -> char {
    if r < 0 || c < 0 { return ' '; }
    grid.get(r as usize).and_then(|row| row.get(c as usize)).copied().unwrap_or(' ')
}

fn is_h_basic(ch: char) -> bool { matches!(ch, '-' | '~' | '+') }
fn is_v_basic(ch: char) -> bool { matches!(ch, '|' | '+') }

fn render_svg(input: &str, opts: &Options) -> String {
    let grid = normalize_input(input);
    let rows = grid.len().max(1);
    let cols = grid.iter().map(|r| r.len()).max().unwrap_or(0).max(1);
    let width = ((cols as i32 + 1) * 8) as f32 * opts.scale;
    let height = ((rows as i32 + 1) * 16) as f32 * opts.scale;

    let mut used: HashSet<(usize, usize)> = HashSet::new();
    let mut elems: Vec<Elem> = Vec::new();
    let mut seq = 0usize;

    detect_rects(&grid, &mut used, &mut elems, opts, &mut seq);

    let mut lines: Vec<LineSeg> = Vec::new();
    let mut polygons: Vec<Elem> = Vec::new();
    collect_lines_and_markers(&grid, &mut used, &mut lines, &mut polygons, opts, &mut seq);

    // Text is collected before line components are appended; final sorting by row/x
    // reproduces the usual left-to-right interleaving of text and strokes.
    collect_text(&grid, &used, &mut elems, opts, &mut seq);

    let line_elems = build_line_elements(lines, opts, &mut seq);
    elems.extend(polygons);
    elems.extend(line_elems);
    elems.sort_by(|a,b| a.key.cmp(&b.key).then(a.seq.cmp(&b.seq)));

    let mut out = String::new();
    out.push_str(&format!("<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"{}\" height=\"{}\" class=\"svgbob\">\n", fmt_f(width), fmt_f(height)));
    out.push_str(&style_defs(opts));
    out.push_str(&format!("  <rect class=\"backdrop\" x=\"0\" y=\"0\" width=\"{}\" height=\"{}\"></rect>\n", fmt_f(width), fmt_f(height)));
    for e in elems { out.push_str(&e.body); }
    out.push_str("</svg>\n");
    out
}

